const body = $json.body ?? {};
const pregunta = typeof body.pregunta === 'string' ? body.pregunta : $json.pregunta;

if (typeof pregunta !== 'string' || pregunta.trim() === '') {
  return [{ json: { ok: false, error: { code: 'INVALID_INPUT', message: 'La propiedad pregunta debe existir, ser string y no estar vacía.' } } }];
}

return [{ json: { ...$json, ok: true, pregunta: pregunta.trim() } }];

const item = $input.first().json;

function cargarMapa() {
  if (item.file_ids && typeof item.file_ids === 'object') return item.file_ids;
  try {
    const m = $('Armar mapa file_ids').first().json.file_ids;
    if (m && typeof m === 'object') return m;
  } catch (e) {}
  return {};
}

const fileIds = cargarMapa();
const seleccionados = Array.isArray(item.fragmentos_seleccionados) ? item.fragmentos_seleccionados.map(String) : [];

if (!seleccionados.length) {
  return [{json:{...item, ok:false, documentos:[], documentos_count:0, error:{code:'NO_BM25_FRAGMENTS', message:'El ranking BM25 no encontro fragmentos relevantes para los seminarios detectados.'}}}];
}

function seminarioDe(nombre) {
  const m = /^S0*(\d{1,2})(bis)?_p\d+-\d+\.pdf$/i.exec(nombre);
  return m ? String(Number(m[1])) + (m[2] ? 'bis' : '') : null;
}
function rangoDe(nombre) {
  const m = /_p(\d+)-(\d+)\.pdf$/i.exec(nombre);
  return m ? {desde:Number(m[1]), hasta:Number(m[2])} : null;
}

const documentos = [];
for (const archivo of seleccionados) {
  const fileId = fileIds[archivo];
  const sem = seminarioDe(archivo);
  const rango = rangoDe(archivo);
  if (!sem || !rango || typeof fileId !== 'string' || !fileId.trim()) continue;
  documentos.push({
    type: 'document',
    source: {type:'file', file_id:fileId},
    title: `Seminario ${sem} \u2014 ${archivo} \u2014 paginas originales ${rango.desde}-${rango.hasta}`,
    citations: {enabled:true},
    metadata: {seminario:sem, archivo, pagina_desde:rango.desde, pagina_hasta:rango.hasta}
  });
}

if (!documentos.length) {
  return [{json:{...item, ok:false, documentos:[], documentos_count:0, error:{code:'NO_SEMINAR_DOCUMENTS', message:'Los fragmentos seleccionados por BM25 no tienen file_id en lacan_file_ids. Verifica la tabla o el mapa de file_ids.'}}}];
}
return [{json:{...item, ok:true, documentos, documentos_count:documentos.length, corpus_tipo:'seminarios_originales'}}];

const p = $json.pregunta.toLowerCase();
const externos = ['buscá en internet','busca en internet','investigá afuera','investiga afuera','fuentes externas','literatura reciente','actualidad','artículos recientes','búsqueda externa','busqueda externa','google'];
const intencion = externos.some(x => p.includes(x)) ? 'investigacion_externa' : 'documental';
return [{ json: { ...$json, intencion } }];

const d = $json;
const documentos = Array.isArray(d.documentos) ? d.documentos : [];
const seminarios = Array.isArray(d.seminarios_detectados) ? d.seminarios_detectados : [];
const semA = seminarios[0] || null;
const semB = seminarios[1] || null;
const autor_a_encontrado = semA ? documentos.some(doc => doc.metadata && doc.metadata.seminario === semA) : false;
const autor_b_encontrado = semB ? documentos.some(doc => doc.metadata && doc.metadata.seminario === semB) : false;
return [{json:{...d, documentos_comparador: documentos, seminario_a: semA, seminario_b: semB, autor_a_encontrado, autor_b_encontrado, autores_faltantes: []}}];

const docs = Array.isArray($json.documentos) ? $json.documentos : [];
const seminarios = Array.isArray($json.seminarios_detectados) ? $json.seminarios_detectados : [];
const objetivo = seminarios.length === 1 ? seminarios[0] : null;
return [{json:{...$json, documentos: docs, seminario_objetivo: objetivo, autor_objetivo: objetivo, autor_encontrado: docs.length > 0}}];

const items=$input.first().json.items||[]; const resultados=items.map(i=>`Fuente: ${i.title}
URL: ${i.link}
Extracto: ${i.snippet}`).join('

'); return [{json:{busqueda_academica:resultados||'Sin resultados en fuentes externas.'}}];

const blocks = $json.content || [];
let texto = '';
const citas = [];
const documentos = ($('Armar documentos (file_id)').item.json.documentos) || [];
for (const b of blocks) {
  if (b.type === 'text') {
    texto += b.text;
    if (b.citations) for (const c of b.citations) {
      const doc = (typeof c.document_index === 'number') ? documentos[c.document_index] : null;
      const meta = doc && doc.metadata ? doc.metadata : null;
      // OJO: nombre de campo de página sin confirmar contra una respuesta real de la API;
      // se prueban los candidatos más probables y se conserva el objeto crudo igual.
      const pagina_relativa = (typeof c.start_page_number === 'number') ? c.start_page_number
        : (typeof c.page_number === 'number') ? c.page_number : null;
      const pagina_original = (meta && pagina_relativa !== null) ? (meta.pagina_desde + pagina_relativa - 1) : null;
      citas.push({
        ...c,
        documento_titulo: c.document_title || (doc ? doc.title : null),
        seminario: meta ? meta.seminario : null,
        archivo: meta ? meta.archivo : null,
        pagina_relativa,
        pagina_original
      });
    }
  }
}
return [{json:{respuesta_v1_texto: texto, citas_v1: citas}}];

