const item = $input.first().json;
const pregunta = String(item.pregunta || '');
let fileIds = item.file_ids && typeof item.file_ids === 'object' ? item.file_ids : {};
if (!Object.keys(fileIds).length && $env.LACAN_FILE_IDS_JSON) { try { fileIds = JSON.parse($env.LACAN_FILE_IDS_JSON); } catch(e) {} }
const disponibles = [...new Set(Object.keys(fileIds).map(n => { const m=/^S0*(\d{1,2})(bis)?_p\d+-\d+\.pdf$/i.exec(n); return m ? String(Number(m[1]))+(m[2]?'bis':'') : null; }).filter(Boolean))];
const p = pregunta.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const found = new Set();
for (const m of p.matchAll(/\bs0*(\d{1,2})(bis)?\b/gi)) found.add(String(Number(m[1]))+(m[2]?'bis':''));
for (const m of p.matchAll(/\bseminario\s+(?:n[º°]?\s*)?0*(\d{1,2})(?:\s*(bis))?\b/gi)) found.add(String(Number(m[1]))+(m[2]?'bis':''));
const explicitos = [...found].filter(x => disponibles.length ? disponibles.includes(x) : true);
return [{json:{...item, file_ids:fileIds, seminarios_disponibles:disponibles, seminarios_explicitos:explicitos, seminarios_detectados:explicitos, tiene_seminario_explicito:explicitos.length>0, requiere_inferencia:explicitos.length===0}}];

const item = $input.first().json;
const ctx = $('Detectar seminario explícito').first().json;
const text = (item.content||[]).filter(x=>x.type==='text').map(x=>x.text||'').join('').replace(/^```json\s*/i,'').replace(/\s*```$/,'').trim();
let parsed = {};
try { parsed = JSON.parse(text); } catch(e) {}
const allowed = new Set((ctx.seminarios_disponibles||[]).map(String));
const sem = Array.isArray(parsed.seminarios)
  ? parsed.seminarios.map(String).map(x=>x.toLowerCase().trim()).filter(x=>allowed.has(x)).slice(0,2)
  : [];
return [{json:{...ctx, seminarios_detectados: sem, confianza_inferencia: Number.isFinite(Number(parsed.confianza)) ? Math.max(0, Math.min(1, Number(parsed.confianza))) : 0, inferencia_valida: sem.length>0}}];

// Detecta si la pregunta involucra dos seminarios (para Comparador)
// y si tiene forma de afirmación a verificar (para Verificador),
// usando los seminarios YA detectados/inferidos mas arriba en el flujo
// (Detectar seminario explicito / Parsear inferencia seminario),
// en vez de una lista fija de autores/comentaristas que no tiene
// sentido contra un corpus de fragmentos de seminarios.
const patrones = [/es cierto que/i,/es verdad que/i,/confirm[aá] si/i,/verific[aá] si/i,/¿(es|fue|dijo|plante[oó]|sostuvo)\b.*\?/i,/seg[uú]n lacan/i];
const pregunta = $json.pregunta;
const patron = patrones.some(r => r.test(pregunta));
const seminarios = Array.isArray($json.seminarios_detectados) ? $json.seminarios_detectados : [];
return [{ json: { ...$json, dos_seminarios_detectados: seminarios.length >= 2, patron_verificacion_detectado: patron } }];

const pregunta = $json.pregunta;
const preguntaValida = typeof pregunta === 'string' && pregunta.trim() !== '';
if (!preguntaValida) {
  return [{json:{...$json, google_query_valida:false,
    ok:false, error:{code:'GOOGLE_QUERY_INVALID',
    message:'No se pudo armar la consulta a Google Custom Search: falta la pregunta.'}}}];
}
return [{json:{...$json, google_query: pregunta, google_query_valida:true}}];

const filas = $input.all().map(i => i.json);
const file_ids = {};
for (const f of filas) {
  if (f.archivo && f.file_id) file_ids[String(f.archivo)] = String(f.file_id);
}
const base = $('Validar entrada').first().json;
return [{ json: { ...base, file_ids, file_ids_count: Object.keys(file_ids).length } }];

function tokenizar(texto) {
  return (texto.toLowerCase().match(/[a-z\u00e1\u00e9\u00ed\u00f3\u00fa\u00f1\u00fc0-9]+/gi) || []);
}

const ctx = $input.first().json;
const pregunta = String(ctx.pregunta || '');
const queryTerms = [...new Set(tokenizar(pregunta))];

return [{ json: { ...ctx, bm25_query_terms: queryTerms } }];

// ===== Ranking BM25 (Opcion A) -- VERSION DIAGNOSTICO =====
const K1 = 1.5;
const B = 0.75;
const TOP_K = 5;
const N_DOCS = 587;
const AVGDL = 5205.192504258944;

const ctx = $('Preparar ranking BM25').first().json;
const pregunta = String(ctx.pregunta || '');
const seminarios = Array.isArray(ctx.seminarios_detectados) ? ctx.seminarios_detectados.map(String) : [];

const fragmentos = $('Leer fragmentos seminario (BM25)').all().map(i => i.json);
const idfRows = $input.all().map(i => i.json);

if (!seminarios.length) {
  return [{ json: { ...ctx, fragmentos_seleccionados: [], fragmentos_bm25: [], bm25_top_k: TOP_K, bm25_pool_size: 0 } }];
}

function tokenizar(texto) {
  return (texto.toLowerCase().match(/[a-z\u00e1\u00e9\u00ed\u00f3\u00fa\u00f1\u00fc0-9]+/gi) || []);
}
const queryTerms = [...new Set(tokenizar(pregunta))];

const idfMap = {};
for (const r of idfRows) {
  if (r.termino !== undefined && r.termino !== null) {
    idfMap[String(r.termino)] = Number(r.idf_positive);
  }
}

const pool = fragmentos.filter(f => seminarios.includes(String(f.seminario)));

function scoreBM25(termFreq, docLength) {
  let score = 0;
  for (const t of queryTerms) {
    const idf = idfMap[t];
    if (!idf) continue;
    const tf = Number(termFreq[t] || 0);
    if (!tf) continue;
    const numerador = tf * (K1 + 1);
    const denominador = tf + K1 * (1 - B + B * (docLength / AVGDL));
    score += idf * (numerador / denominador);
  }
  return score;
}

let parseErrores = 0;
let primerError = null;

const ranked = pool.map(f => {
  let tf = {};
  try {
    tf = JSON.parse(f.term_freq_json || '{}');
  } catch (e) {
    parseErrores++;
    if (!primerError) primerError = String(e.message);
  }
  const docLength = Number(f.doc_length || 0);
  return { ...f, bm25_score: scoreBM25(tf, docLength) };
}).sort((a, b) => b.bm25_score - a.bm25_score);

const seleccionados = ranked.slice(0, TOP_K);

const primero = pool[0] || {};
const s = String(primero.term_freq_json || '');
let tfPrimero = null;
try { tfPrimero = JSON.parse(s); } catch (e) {}

const debug = {
  parse_errores: parseErrores,
  primer_error: primerError,
  idf_por_termino: Object.fromEntries(queryTerms.map(t => [t, idfMap[t] ?? null])),
  primer_fragmento: primero.archivo || null,
  tipo_term_freq_json: typeof primero.term_freq_json,
  largo_term_freq_json: s.length,
  ultimos_40_caracteres: s.slice(-40),
  cantidad_terminos_tf: tfPrimero ? Object.keys(tfPrimero).length : -1,
  tf_de_terminos_query: tfPrimero ? Object.fromEntries(queryTerms.map(t => [t, tfPrimero[t] ?? 0])) : null,
  doc_length_primero: primero.doc_length ?? null
};

return [{
  json: {
    ...ctx,
    fragmentos_seleccionados: seleccionados.map(f => f.archivo),
    fragmentos_bm25: seleccionados.map(f => ({ archivo: f.archivo, seminario: f.seminario, score: f.bm25_score })),
    bm25_top_k: TOP_K,
    bm25_pool_size: pool.length,
    bm25_query_terms: queryTerms,
    bm25_debug: debug
  }
}];
